#!/bin/bash
# Build 23: upstream nx2 bf4c42e2 with #570 (128 banks), #268, #313 and the unbacked image fix.
set -eux
UP=${UPSTREAM:-https://github.com/zortos293/lichii}
if [ -z "${LOCAL_ONLY:-}" ]; then
  git fetch -q "$UP" bf4c42e223d4812d4456d3d8f66d892571d19a13 82d48cc7eeb9c641da3f923282940c3871e58cb9 4262a993e32a984061dd277669653978ea2d5da6 09d20d291a1935a12e112eb3f9fe23e225e59bb6
fi
git checkout -q --detach bf4c42e223d4812d4456d3d8f66d892571d19a13
git cherry-pick -x 82d48cc7eeb9c641da3f923282940c3871e58cb9 >/dev/null
git cherry-pick -x 4262a993e32a984061dd277669653978ea2d5da6 >/dev/null
git cherry-pick -x e15125b73cf27c4a139f7759f0d7d0722ab80114 >/dev/null
git merge -q --no-ff -m "Merge upstream PR #313 (keep Switch 2 pipelines built)" 09d20d291a1935a12e112eb3f9fe23e225e59bb6
echo "" | base64 -d > "${RUNNER_TEMP:-/tmp}/query128.patch"
git am -q -C2 --keep-cr "${RUNNER_TEMP:-/tmp}/query128.patch"
test "$(git rev-parse 'HEAD^{tree}')" = ab61e42484778b4d772b1660497c7efd08b6fa43
for f in $(git ls-tree -r --name-only HEAD .github); do
  git cat-file -e "fork_tip:$f" 2>/dev/null || git rm -q "$f"
done
git checkout fork_tip -- .github
git commit -q -m "Keep this fork's workflow files" || true
test -z "$(git diff fork_tip HEAD -- .github)"
TREE=$(git rev-parse 'HEAD^{tree}')
echo "final tree $TREE"
NEW=$(git commit-tree "$TREE" -p fork_tip -p HEAD -m "Build 23: upstream nx2 bf4c42e2 with #570 (128 banks), #268, #313 and the unbacked image fix")
git checkout -q --detach "$NEW"
